:root {
  --bg-1: #f4f1ea;
  --bg-2: #fdf7f1;
  --ink: #1f1f1f;
  --muted: #6a6a6a;
  --card: #ffffff;
  --accent: #1b4965;
  --accent-2: #ca6b4e;
  --border: #e5ddd2;
  --shadow: 0 16px 30px rgba(31, 31, 31, 0.08);
  --font-title: "Georgia", "Palatino Linotype", "Book Antiqua", serif;
  --font-body: "Trebuchet MS", "Lucida Sans Unicode", "Lucida Grande", sans-serif;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: var(--font-body);
  color: var(--ink);
  background: radial-gradient(circle at top left, rgba(202, 107, 78, 0.12), transparent 45%),
    radial-gradient(circle at 20% 30%, rgba(27, 73, 101, 0.12), transparent 55%),
    linear-gradient(135deg, var(--bg-1), var(--bg-2));
  min-height: 100vh;
}

.page {
  max-width: 1200px;
  margin: 0 auto;
  padding: 28px 24px 40px;
}

header {
  margin-bottom: 20px;
}

header h1 {
  font-family: var(--font-title);
  font-size: 32px;
  margin: 0 0 6px;
  letter-spacing: 0.4px;
}

header p {
  margin: 0;
  color: var(--muted);
  font-size: 14px;
}

.grid {
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 22px;
  align-items: start;
}

.card {
  background: var(--card);
  border-radius: 16px;
  padding: 18px 18px 16px;
  box-shadow: var(--shadow);
  border: 1px solid rgba(229, 221, 210, 0.8);
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 12px;
}

.card-header h2 {
  font-family: var(--font-title);
  font-size: 20px;
  margin: 0;
  color: var(--accent);
}

#legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 12px;
  font-size: 12px;
  color: var(--muted);
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.legend-swatch {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  border: 1px solid rgba(31, 31, 31, 0.15);
}

.chart-wrap {
  background: linear-gradient(180deg, rgba(253, 247, 241, 0.7), rgba(244, 241, 234, 0.4));
  border-radius: 14px;
  padding: 10px;
  border: 1px dashed rgba(27, 73, 101, 0.18);
}

#bubble-chart {
  width: 100%;
  height: 520px;
}

.node circle {
  stroke: rgba(0, 0, 0, 0.15);
  stroke-width: 1.2px;
}

.node text {
  font-size: 12px;
  fill: #1a1a1a;
  pointer-events: none;
}

.node.selected circle {
  stroke: var(--accent-2);
  stroke-width: 3px;
}

.table-wrap {
  max-height: 560px;
  overflow: auto;
  border-radius: 12px;
  border: 1px solid var(--border);
}

#stock-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13px;
}

#stock-table thead th {
  position: sticky;
  top: 0;
  background: #faf7f2;
  text-align: left;
  padding: 10px 8px;
  font-weight: 600;
  color: var(--accent);
  border-bottom: 1px solid var(--border);
}

#stock-table tbody td {
  padding: 8px;
  border-bottom: 1px solid rgba(229, 221, 210, 0.7);
}

#stock-table tbody tr {
  cursor: pointer;
  transition: background 0.1s ease;
}

#stock-table tbody tr:hover {
  background: rgba(27, 73, 101, 0.06);
}

#stock-table tbody tr.selected {
  background: rgba(202, 107, 78, 0.18);
}

#stock-table tbody td:last-child {
  text-align: right;
  font-variant-numeric: tabular-nums;
}

.tooltip {
  position: absolute;
  padding: 10px 12px;
  background: rgba(27, 31, 36, 0.92);
  color: #fff;
  border-radius: 6px;
  font-size: 12px;
  pointer-events: none;
  opacity: 0;
  transform: translateY(-4px);
  transition: opacity 0.15s ease;
  z-index: 10;
}

.tooltip.visible {
  opacity: 1;
}

@media (max-width: 980px) {
  .grid {
    grid-template-columns: 1fr;
  }

  #bubble-chart {
    height: 460px;
  }

  .table-wrap {
    max-height: none;
  }
}
