{"cmd":"cat > /root/output/js/visualization.js <<'JS'
/* Deterministic D3 v6 visualization for stock dataset. */

const width = 720;
const height = 520;
const chartPadding = 18;

const svg = d3
  .select('#bubble-chart')
  .attr('viewBox', `0 0 ${width} ${height}`)
  .attr('preserveAspectRatio', 'xMidYMid meet');

const tooltip = d3.select('#tooltip');

const colorRange = [
  '#1f6f8b',
  '#e07a5f',
  '#81b29a',
  '#f2cc8f',
  '#3d405b',
  '#8ab17d',
  '#c8553d'
];

const numberShort = (value) => {
  const abs = Math.abs(value);
  if (abs >= 1e12) return `${trimZeros((value / 1e12).toFixed(2))}T`;
  if (abs >= 1e9) return `${trimZeros((value / 1e9).toFixed(2))}B`;
  if (abs >= 1e6) return `${trimZeros((value / 1e6).toFixed(2))}M`;
  if (abs >= 1e3) return `${trimZeros((value / 1e3).toFixed(2))}K`;
  return value ? value.toString() : 'N/A';
};

const trimZeros = (value) => value.replace(/\.00$/, '').replace(/(\.\d)0$/, '$1');

const parseRow = (d) => ({
  ticker: d.ticker,
  sector: d.sector,
  fullName: d['full name'],
  marketCap: d.marketCap ? Number(d.marketCap) : NaN
});

d3.csv('data/stock-descriptions.csv', parseRow).then((raw) => {
  const data = raw
    .filter((d) => d.ticker)
    .sort(
      (a, b) =>
        d3.ascending(a.sector, b.sector) || d3.ascending(a.ticker, b.ticker)
    );

  data.forEach((d, i) => {
    d.isEtf = !Number.isFinite(d.marketCap) || d.sector === 'ETF';
    d.index = i;
  });

  const sectors = Array.from(new Set(data.map((d) => d.sector))).sort(
    d3.ascending
  );

  const color = d3.scaleOrdinal().domain(sectors).range(colorRange);

  buildLegend(sectors, color);

  const caps = data.filter((d) => !d.isEtf).map((d) => d.marketCap);
  const rScale = d3
    .scaleSqrt()
    .domain([d3.min(caps), d3.max(caps)])
    .range([10, 42]);
  const etfRadius = 12;

  const columns = Math.ceil(Math.sqrt(data.length));
  const spacingX = (width - chartPadding * 2) / (columns + 1);
  const spacingY = (height - chartPadding * 2) / (columns + 1);

  data.forEach((d, i) => {
    const col = i % columns;
    const row = Math.floor(i / columns);
    d.radius = d.isEtf ? etfRadius : rScale(d.marketCap);
    d.x = chartPadding + spacingX * (col + 1);
    d.y = chartPadding + spacingY * (row + 1);
    d.vx = 0;
    d.vy = 0;
  });

  const center = { x: width / 2, y: height / 2 };
  const ringRadius = Math.min(width, height) * 0.25;
  const sectorCenters = {};
  sectors.forEach((sector, i) => {
    const angle = (i / sectors.length) * Math.PI * 2;
    sectorCenters[sector] = {
      x: center.x + ringRadius * Math.cos(angle),
      y: center.y + ringRadius * Math.sin(angle)
    };
  });

  const node = svg
    .append('g')
    .attr('class', 'nodes')
    .selectAll('g')
    .data(data)
    .enter()
    .append('g')
    .attr('class', 'node')
    .attr('data-ticker', (d) => d.ticker)
    .on('mouseover', (event, d) => {
      if (d.isEtf) return;
      tooltip
        .classed('visible', true)
        .html(
          `<strong>${d.ticker}</strong><br/>${d.fullName}<br/>${d.sector}`
        );
    })
    .on('mousemove', (event, d) => {
      if (d.isEtf) return;
      tooltip
        .style('left', `${event.pageX + 12}px`)
        .style('top', `${event.pageY - 12}px`);
    })
    .on('mouseout', () => {
      tooltip.classed('visible', false);
    })
    .on('click', (event, d) => {
      setSelected(d.ticker);
    });

  node
    .append('circle')
    .attr('r', (d) => d.radius)
    .attr('fill', (d) => color(d.sector));

  node
    .append('text')
    .attr('text-anchor', 'middle')
    .attr('dy', '0.35em')
    .text((d) => d.ticker)
    .style('font-size', (d) => `${Math.max(9, Math.min(14, d.radius * 0.6))}px`);

  const simulation = d3
    .forceSimulation(data)
    .force(
      'x',
      d3
        .forceX((d) => sectorCenters[d.sector].x)
        .strength(0.12)
    )
    .force(
      'y',
      d3
        .forceY((d) => sectorCenters[d.sector].y)
        .strength(0.12)
    )
    .force('collide', d3.forceCollide((d) => d.radius + 2).iterations(2))
    .force('charge', d3.forceManyBody().strength(-5))
    .force('center', d3.forceCenter(center.x, center.y))
    .stop();

  const ticks = 240;
  for (let i = 0; i < ticks; i += 1) {
    simulation.tick();
  }

  node.attr('transform', (d) => `translate(${d.x},${d.y})`);

  buildTable(data, (ticker) => setSelected(ticker));

  let selectedTicker = null;

  function setSelected(ticker) {
    selectedTicker = ticker === selectedTicker ? null : ticker;

    node.classed('selected', (d) => d.ticker === selectedTicker);
    d3.selectAll('#stock-table tbody tr').classed(
      'selected',
      (d) => d.ticker === selectedTicker
    );
  }

  function buildTable(rows, onSelect) {
    const tbody = d3.select('#stock-table tbody');
    const tr = tbody
      .selectAll('tr')
      .data(rows)
      .enter()
      .append('tr')
      .attr('data-ticker', (d) => d.ticker)
      .on('click', (event, d) => {
        onSelect(d.ticker);
      });

    tr.append('td').text((d) => d.ticker);
    tr.append('td').text((d) => d.fullName);
    tr.append('td').text((d) => d.sector);
    tr.append('td').text((d) => (d.isEtf ? 'N/A' : numberShort(d.marketCap)));
  }
});

function buildLegend(sectors, color) {
  const legend = d3.select('#legend');
  const items = legend
    .selectAll('div')
    .data(sectors)
    .enter()
    .append('div')
    .attr('class', 'legend-item');

  items
    .append('span')
    .attr('class', 'legend-swatch')
    .style('background', (d) => color(d));

  items.append('span').text((d) => d);
}
JS"}

